import{_ as a,o as t,c as r,a3 as s}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse(`{"title":"Gestionnaire de thème « Frosted Glass »","description":"Informations concernant le gestionnaire de thème « Frosted Glass » et la variante d'interface utilisateur (UIX) testée.","frontmatter":{"title":"Gestionnaire de thème « Frosted Glass »","description":"Informations concernant le gestionnaire de thème « Frosted Glass » et la variante d'interface utilisateur (UIX) testée."},"headers":[],"relativePath":"fr/collection/frosted-glass-manager/index.md","filePath":"fr/collection/frosted-glass-manager/index.md","lastUpdated":1793447386000}`),i={name:"fr/collection/frosted-glass-manager/index.md"};function o(n,e,l,d,m,g){return t(),r("div",null,[...e[0]||(e[0]=[s('<p><a id="frosted-glass-theme-gestionnaire"></a><a id="orientation-actuelle"></a></p><h1 id="frosted-glass-theme-manager" tabindex="-1">Gestionnaire de thème « Frosted Glass » <a class="header-anchor" href="#frosted-glass-theme-manager" aria-label="Permalink to &quot;Gestionnaire de thème « Frosted Glass » {#frosted-glass-theme-manager}&quot;">​</a></h1><p>Le « Frosted Glass Theme Manager » est une intégration personnalisée pour Home Assistant, conçue pour générer des fichiers de thèmes de type « verre dépoli » (frosted glass). Les couleurs et les images d&#39;arrière-plan peuvent être définies via l&#39;interface de Home Assistant.</p><div class="warning custom-block"><p class="custom-block-title">Note non officielle</p><p>Cette page ne constitue pas une documentation officielle du projet. Le dépôt (repository) original demeure la référence.</p></div><table tabindex="0"><thead><tr><th>Champ</th><th>Valeur</th></tr></thead><tbody><tr><td>Projet original</td><td><a href="https://github.com/wessamlauf/frosted-glass-manager" target="_blank" rel="noreferrer">wessamlauf/frosted-glass-manager</a></td></tr><tr><td>Fork avec variante de test UIX</td><td><a href="https://github.com/rockbaer2007/frosted-glass-manager/tree/experiment/uix-theme-manager" target="_blank" rel="noreferrer">rockbaer2007/frosted-glass-manager</a></td></tr><tr><td>Pull Request</td><td><a href="https://github.com/wessamlauf/frosted-glass-manager/pull/15" target="_blank" rel="noreferrer">wessamlauf/frosted-glass-manager#15</a></td></tr><tr><td>Catégorie</td><td>Intégrations HA</td></tr></tbody></table><h2 id="original-manager" tabindex="-1">Gestionnaire original <a class="header-anchor" href="#original-manager" aria-label="Permalink to &quot;Gestionnaire original {#original-manager}&quot;">​</a></h2><p>Le gestionnaire original génère des fichiers de thèmes de type « verre dépoli » destinés à une utilisation standard avec « card-mod ».</p><p><a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=wessamlauf&amp;repository=frosted-glass-manager&amp;category=integration" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/hacs_repository.svg" alt="Ouvrir Frosted Glass Theme Manager dans HACS"></a></p><p>Dépôt :</p><ul><li><a href="https://github.com/wessamlauf/frosted-glass-manager" target="_blank" rel="noreferrer">wessamlauf/frosted-glass-manager</a></li></ul><h2 id="uix-testvariante" tabindex="-1">Variante de test UIX <a class="header-anchor" href="#uix-testvariante" aria-label="Permalink to &quot;Variante de test UIX {#uix-testvariante}&quot;">​</a></h2><p>Pour les installations utilisant UIX au lieu de card-mod, une version fonctionnelle basée sur UIX est disponible sous forme de « fork ».</p><p><a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=rockbaer2007&amp;repository=frosted-glass-manager&amp;category=integration" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/hacs_repository.svg" alt="Ouvrir Frosted Glass UIX Theme Manager dans HACS"></a></p><p>Dépôt :</p><ul><li><a href="https://github.com/rockbaer2007/frosted-glass-manager/tree/experiment/uix-theme-manager" target="_blank" rel="noreferrer">Frosted Glass UIX Theme Manager</a></li></ul><p>La variante de test UIX utilise son propre identifiant d&#39;intégration pour Home Assistant :</p><ul><li><code>frosted_glass_uix_manager</code></li></ul><p>Elle génère ses propres fichiers de thème, évitant ainsi tout conflit avec les noms de fichiers habituels de Frosted Glass :</p><ul><li><code>Frosted Glass UIX Custom.yaml</code></li><li><code>Frosted Glass UIX Custom Lite.yaml</code></li></ul><p>Les arrière-plans par défaut sont fournis localement et copiés dans Home Assistant au démarrage :</p><ul><li><code>config/www/frosted-glass-uix/frosted-glass-light-background.jpg</code></li><li><code>config/www/frosted-glass-uix/frosted-glass-dark-background.jpg</code></li></ul><p>Dans les thèmes générés, ils sont intégrés via <code>/local/frosted-glass-uix/...</code>. Ainsi, l&#39;apparence par défaut ne dépend pas d&#39;un CDN externe.</p><h2 id="hinweis" tabindex="-1">Remarque <a class="header-anchor" href="#hinweis" aria-label="Permalink to &quot;Remarque {#hinweis}&quot;">​</a></h2><p>La variante de test UIX a fait l&#39;objet de tests pratiques, mais elle demeure une version expérimentale. Pour toute question générale concernant le projet original, veuillez continuer à utiliser le dépôt (repository) d&#39;origine.</p>',24)])])}const u=a(i,[["render",o]]);export{c as __pageData,u as default};
